#include <iostream>
#include <cstdlib>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    cin >> a >> b;

    int operations = 0;

    for (long long prime : {2LL, 3LL, 5LL}) {
        int exponentA = 0;
        int exponentB = 0;

        while (a % prime == 0) {
            a /= prime;
            ++exponentA;
        }

        while (b % prime == 0) {
            b /= prime;
            ++exponentB;
        }

        operations += abs(exponentA - exponentB);
    }

    cout << (a == b ? operations : -1);
    return 0;
}

